#define NUM_SPHERES 100
#define BEAT_INTERVAL 0.46875 // 60 / 128 BPM
#define TWO_BEAT_INTERVAL (BEAT_INTERVAL * 2.0) // 2 beats interval
#define FOUR_BEAT_INTERVAL (BEAT_INTERVAL * 4.0) // 4 beats interval

// Pseudo-random float generator
float hash(float n) {
    return fract(sin(n) * 43758.5453);
}

// Pseudo-random vec3 generator
vec3 hash3(float n) {
    return fract(sin(vec3(n, n + 1.0, n + 2.0)) * vec3(43758.5453, 22578.1459, 19642.3491));
}

// Optimized smooth minimum function
float smin(float a, float b, float k) {
    float h = max(k - abs(a - b), 0.0) / k;
    return min(a, b) - h * h * k * 0.25;
}

// Distance to a sphere
float sdSphere(vec3 p, float r) {
    return length(p) - r;
}

// Distance to the scene (optimized)
float map(vec3 p) {
    float dist = 1e6;

    for (int i = 0; i < NUM_SPHERES; i++) {
        float id = float(i);
        vec3 offset = hash3(id) * 10.0 - 5.0; // Random initial position
        float time = iTime * 0.5 + hash(id) * 2.0; // Time offset for animation

        // Determine if this sphere should change size
        float sizeChangeFactor = 0.0;
        if (hash(id + 123.456) < 0.3) { // 15%-30% of spheres (adjust hash threshold)
            float beatProgress = mod(iTime, FOUR_BEAT_INTERVAL) / FOUR_BEAT_INTERVAL;
            sizeChangeFactor = smoothstep(0.0, 1.0, beatProgress) * smoothstep(1.0, 0.0, beatProgress);
        }

        // Scale modulation
        float scale = 0.5 + sizeChangeFactor * 2.6; // Scale changes by 30%

        // Organic movement using sine/cosine waves
        vec3 spherePos = offset + vec3(sin(time + id), cos(time + id * 0.7), sin(time + id * 0.3)) * 2.0;
        float sphereDist = sdSphere(p - spherePos, scale);

        // Smooth blending between spheres
        dist = smin(dist, sphereDist, 0.5);
    }

    return dist;
}

// Normal calculation (optimized)
vec3 getNormal(vec3 p) {
    vec2 e = vec2(0.001, 0.0);
    return normalize(vec3(
        map(p + e.xyy) - map(p - e.xyy),
        map(p + e.yxy) - map(p - e.yxy),
        map(p + e.yyx) - map(p - e.yyx)
    ));
}

// Get primary light position at the current time
vec3 getPrimaryLightPosition(float time) {
    float beat = floor(time / BEAT_INTERVAL); // Current beat number
    float t = fract(time / BEAT_INTERVAL); // Progress within the current beat

    // Random light positions for the current and next beat
    vec3 lightPosCurrent = hash3(beat) * 20.0 - 10.0; // Random position in [-10, 10] range
    vec3 lightPosNext = hash3(beat + 1.0) * 20.0 - 10.0; // Next random position

    // Smoothly interpolate between current and next position
    return mix(lightPosCurrent, lightPosNext, smoothstep(0.0, 1.0, t));
}

// Get secondary light position and intensity
vec3 getSecondaryLight(float time, out float intensity) {
    float beat = floor(time / TWO_BEAT_INTERVAL); // Current 2-beat interval
    float t = fract(time / TWO_BEAT_INTERVAL); // Progress within the 2-beat interval

    // Random light position changes every 4th beat
    vec3 lightPosCurrent = hash3(beat * 0.5) * 20.0 - 10.0; // Random position in [-10, 10] range
    vec3 lightPosNext = hash3((beat + 1.0) * 0.5) * 20.0 - 10.0; // Next random position

    // Smoothly interpolate between current and next position
    vec3 lightPos = mix(lightPosCurrent, lightPosNext, smoothstep(0.0, 1.0, t * 2.0));

    // Strobe intensity: fade out over 2 beats
    intensity = 1.0 - smoothstep(0.0, 1.0, t);

    return lightPos;
}

// Raymarching with early exit and adaptive steps
vec3 raymarch(vec3 ro, vec3 rd, vec3 primaryLightPos, vec3 secondaryLightPos, float secondaryLightIntensity) {
    vec3 p = ro;
    float t = 0.0;

    for (int i = 0; i < 48; i++) { // Reduced steps for performance
        float d = map(p);
        if (d < 0.001) break; // Early exit if close enough
        if (t > 30.0) return vec3(0.0); // Exit if too far
        t += d * 0.7; // Adaptive step size
        p = ro + rd * t;
    }

    if (t > 30.0) return vec3(0.0); // Background color

    vec3 normal = getNormal(p);

    // Primary light contribution
    vec3 primaryLightDir = normalize(primaryLightPos - p);
    float primaryDiff = max(dot(normal, primaryLightDir), 0.0);
    vec3 primaryReflectDir = reflect(-primaryLightDir, normal);
    float primarySpec = pow(max(dot(rd, primaryReflectDir), 0.0), 32.0);

    // Secondary light contribution
    vec3 secondaryLightDir = normalize(secondaryLightPos - p);
    float secondaryDiff = max(dot(normal, secondaryLightDir), 0.0) * secondaryLightIntensity;
    vec3 secondaryReflectDir = reflect(-secondaryLightDir, normal);
    float secondarySpec = pow(max(dot(rd, secondaryReflectDir), 0.0), 32.0) * secondaryLightIntensity;

    vec3 albedo = vec3(0.8, 0.8, 0.8); // Chrome color
    vec3 color = albedo * (primaryDiff + secondaryDiff) + vec3(1.0) * (primarySpec + secondarySpec);

    return color;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord / iResolution.xy) * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    vec3 ro = vec3(0.0, 0.0, 7.0); // Camera position
    vec3 rd = normalize(vec3(uv, -1.0)); // Ray direction

    // Get the primary light position synchronized to 128 BPM
    vec3 primaryLightPos = getPrimaryLightPosition(iTime);

    // Get the secondary light position and intensity
    float secondaryLightIntensity;
    vec3 secondaryLightPos = getSecondaryLight(iTime, secondaryLightIntensity);

    vec3 color = raymarch(ro, rd, primaryLightPos, secondaryLightPos, secondaryLightIntensity);

    fragColor = vec4(color, 1.0);
}
